-- Results of the pre-registered runs of V014, V015, V017 and V018 on the 2026-10-15T02:05Z reading (stack_cohort_prices).
-- Thresholds and rules are those registered in vein_ledger on 2026-10-15, unchanged after the first look. Each row carries its
-- effect, interval, cohort and lot counts, data as-of time and the raw-spread caveat. V017 could not be graded (28 of 30 three-way cohorts).
BEGIN;
SET LOCAL statement_timeout = '30s';
SET LOCAL lock_timeout = '5s';
INSERT INTO public.vein_runs (vein_id, version, sample, window_from, window_to, n, effect, multiplier, verdict, counts, result, ran_by)
SELECT 'V014', 1, 'confirmation', DATE '2026-10-15', DATE '2026-10-15', 19910, 0.004926, 1.004938, 'refuted', true,
  $j${"as_of": "2026-10-15T02:05:00Z", "data": "stack_cohort_prices reading 2026-10-15T02:05:00Z", "sources": ["bat", "mecum"], "n_cohorts": 227, "lots": {"bat": 9308, "mecum": 10602}, "median_d": 0.004926118336056717, "ci95_bootstrap_2000": [-0.044451762570835385, 0.03955714543124801], "share_cohorts_same_sign_as_median": 0.5066079295154186, "rule_applied": "pre-registered, thresholds unchanged", "caveat": "Raw spread of cohort medians: mileage, condition, buyer's premium treatment and lot mix are not controlled, so a result says whether venues price the same year, make and model differently, not why. Cohort = year + lower make + lower model, string-equal (undercounts true cohorts). Unit of final_price as each source reports it, not converted."}$j$::jsonb, 'claude-code lane-stacks (session skylar-f7 subagent) for the owner, measured 2026-10-15'
WHERE NOT EXISTS (SELECT 1 FROM public.vein_runs r WHERE r.vein_id = 'V014' AND r.sample = 'confirmation');
